template, ct = LINES[0], LINES[1]

def enc(m):
    out = []
    for i, ch in enumerate(m):
        if not ch.isalpha():
            out.append(ch)
        else:
            out.append(chr((ord(ch) - 0x41 + i) % 26 + 0x41))
    return ''.join(out)

def dec(c):
    out = []
    for i, ch in enumerate(c):
        if not ch.isalpha():
            out.append(ch)
        else:
            out.append(chr((ord(ch) - 0x41 - i) % 26 + 0x41))
    return ''.join(out)

pt = dec(ct)
print("ct           :", repr(ct))
print("ct len       :", len(ct))
print("pt           :", repr(pt))
print("pt len       :", len(pt))
print("roundtrip    :", enc(pt) == ct)
print("rt bytes eq  :", enc(pt).encode() == ct.encode())
star = template.count('*')
print("template     :", template)
print("asterisks    :", star, "| pt len:", len(pt), "| equal:", star == len(pt))
print("all pt chars alpha-or-_:", all(ch.isalpha() and ch.isupper() or ch == '_' or ch == '?' or ch == '!' for ch in pt))
